CREATE TABLE IF NOT EXISTS instances (uid TEXT PRIMARY KEY, study_uid TEXT NOT NULL, series_uid TEXT NOT NULL, object_key TEXT NOT NULL, sha256 TEXT NOT NULL, status TEXT NOT NULL, version BIGINT NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS route_jobs (id TEXT PRIMARY KEY, instance_uid TEXT NOT NULL, destination_id TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, action TEXT NOT NULL, subject TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL, at TIMESTAMP NOT NULL);
